const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));for(const [button,id] of [['enquiry-open','enquiry'],['privacy-open','privacy']])document.getElementById(button).addEventListener('click',()=>document.getElementById(id).showModal());document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});document.getElementById('brief').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const content=`AMEA Intelligent Systems — Project brief\n\nName: ${data.get('name')}\nWork email: ${data.get('email')}\nOrganisation: ${data.get('organisation')}\n\nWhat we would like to improve:\n${data.get('project')}\n`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='amea-project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('form-status').textContent='Your brief has been downloaded. No enquiry has been sent.'});

(()=>{const tap=document.getElementById('band-tap'),phone=document.getElementById('demo-phone'),screen=document.getElementById('demo-screen'),instruction=document.getElementById('demo-instruction');let timer;function show(state){clearTimeout(timer);phone.classList.remove('approaching');tap.classList.remove('phone-tapping');tap.disabled=false;const views={ready:'<span class="demo-step">Ready to try</span><h3>Help starts with a tap</h3><p>Tap the bracelet beside this phone to open your help screen</p><span class="demo-waiting" aria-hidden="true">↖</span>',help:'<span class="demo-step">Your help page is open</span><h3>How can we help?</h3><p>Your chosen contact is ready to call</p><button class="demo-action" data-demo="call">Call My Nurse</button><button class="demo-action secondary" data-demo="ready">Start again</button>',call:'<span class="demo-step">Simulated call screen</span><div class="demo-avatar" aria-hidden="true">MN</div><h3 class="demo-centre">My Nurse</h3><p class="demo-centre">Call preview only<br>No real call is being placed</p><button class="demo-action end" data-demo="ended">End demo call</button>',ended:'<span class="demo-step">Demo complete</span><h3>That’s how it works</h3><p>In the real service, Call My Nurse would open your phone’s dialler for you to confirm the call</p><button class="demo-action" data-demo="ready">Try again</button>'};screen.innerHTML=views[state]||views.ready;instruction.textContent=state==='ready'?'1 · Select the bracelet to see the phone tap':state==='help'?'2 · Choose Call My Nurse on the phone':state==='call'?'3 · Preview the call screen — no call is placed':'Tap, open help, choose who to contact';screen.querySelectorAll('[data-demo]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.demo)));}tap.addEventListener('click',()=>{clearTimeout(timer);tap.disabled=true;tap.classList.add('phone-tapping');instruction.textContent='The back of the phone moves to the bracelet icon';screen.innerHTML='<span class="demo-step">Phone tapped · Demo</span><h3>Opening your help screen</h3><p>Tap your phone to HelloBand to open your help page</p>';timer=setTimeout(()=>show('help'),2800)});})();
